+      }
     } else if (!catalog_reloader_->last_error().empty()) {
       // 重载失败（YAML 解析或校验不过）：旧目录继续生效，节流告警提示修复文件
       RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
@@ -261,6 +293,27 @@ CallbackReturn DispatcherNode::on_activate(const rclcpp_lifecycle::State& /*stat
   return CallbackReturn::SUCCESS;
 }

+void DispatcherNode::RebuildPlanner() {
+  const double step_size = get_parameter("path_step_size_m").as_double();
+  if (planner_type_ == "skeleton") {
+    planner_ = std::make_unique<amr_dispatcher_core::planning::SkeletonPlanner>(
+        catalog_reloader_ ? catalog_reloader_->catalog()
+                          : amr_dispatcher_core::catalog::StationCatalog{},
+        amr_dispatcher_core::planning::SkeletonPlanner::Config{step_size});
+    RCLCPP_INFO(get_logger(),
+                "Path planner: SkeletonPlanner (mixed-graph polyline, step %.2f m)",
+                step_size);
+    return;
+  }
+  if (planner_type_ != "mock") {
+    RCLCPP_WARN(get_logger(),
+                "Unknown planner_type '%s', falling back to MockLinearPlanner",
+                planner_type_.c_str());
+  }
+  planner_ = std::make_unique<amr_dispatcher_core::MockLinearPlanner>(step_size);
+  RCLCPP_INFO(get_logger(), "Path planner: MockLinearPlanner (step %.2f m)", step_size);
+}
+
 CallbackReturn DispatcherNode::on_deactivate(const rclcpp_lifecycle::State& /*state*/) {
   schedule_timer_.reset();
   deadlock_timer_.reset();
@@ -1329,6 +1382,22 @@ void DispatcherNode::ScheduleTick() {
     return;
   }

+  // 地图版本门禁：配置了期望哈希且目录已加载、且目录哈希非空时，
+  // 哈希不一致即判定环境地图与部署目录不匹配——暂停出队派发。
+  // 直接 return（不消费 queue_start_requested_），哈希恢复一致后派发自动继续。
+  map_version_valid_ = true;
+  if (!expected_map_hash_.empty() && catalog_reloader_ != nullptr &&
+      catalog_reloader_->loaded()) {
+    const auto& catalog = catalog_reloader_->catalog();
+    if (!catalog.map_hash.empty() && catalog.map_hash != expected_map_hash_) {
+      map_version_valid_ = false;
+      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
+                           "Map hash mismatch: expected %s got %s, dispatching paused",
+                           expected_map_hash_.c_str(), catalog.map_hash.c_str());
+      return;
+    }
+  }
+
   // 行为树出队派发门控：runtime 树按"空闲 + 启动请求"给派发决策，
   // 未请求启动时即使队列有任务也不出队（启动请求由提单/入队/结果链武装）。
   amr_dispatcher_bt::MissionRuntimeBehaviorTreeInput runtime_input;
diff --git a/test/unit/test_traffic_planning.cpp b/test/unit/test_traffic_planning.cpp
index 0b7bb93..b5d839e 100644
--- a/test/unit/test_traffic_planning.cpp
+++ b/test/unit/test_traffic_planning.cpp
@@ -361,4 +361,40 @@ TEST(TrafficPlanningTest, PlanMissionRouteLocks_NoPath_ReturnsEmptyLockSet) {
   EXPECT_TRUE(lock_ids.empty());
 }

+TEST(TrafficPlanningTest, PlanMissionRouteLocks_MixedGraph_GeneratesCompleteDeduplicatedLocks) {
+  catalog::StationCatalog catalog;
+  catalog.stations.push_back({"s1", "map", 0.0, 0.0, 0.0, "normal"});
+  catalog.stations.push_back({"s2", "map", 10.0, 0.0, 0.0, "normal"});
+  catalog.road_nodes.push_back({"rn1", "map", 2.0, 0.0, 0.0});
+  catalog.road_nodes.push_back({"rn2", "map", 6.0, 0.0, 0.0});
+
+  catalog.edges.push_back({"s1", "rn1", 2.0, true, true});
+  catalog.edges.push_back({"rn1", "rn2", 4.0, true, true});
+  catalog.edges.push_back({"rn2", "s2", 4.0, true, true});
+
+  const auto lock_ids = PlanMissionRouteLocks(catalog, "s1", "s2");
+
+  // 4 个节点锁 + 3 条边锁 = 7 个锁，去重且保序
+  ASSERT_EQ(lock_ids.size(), 7U);
+  EXPECT_EQ(lock_ids[0], "route_node:s1");
+  EXPECT_EQ(lock_ids[1], "route_node:rn1");
+  EXPECT_EQ(lock_ids[2], "route_node:rn2");
+  EXPECT_EQ(lock_ids[3], "route_node:s2");
+  EXPECT_EQ(lock_ids[4], RouteLockId("s1", "rn1"));
+  EXPECT_EQ(lock_ids[5], RouteLockId("rn1", "rn2"));
+  EXPECT_EQ(lock_ids[6], RouteLockId("rn2", "s2"));
+}
+
+TEST(TrafficReservationTest, BuildRouteLockIds_DeduplicatesWhilePreservingOrder) {
+  // 路径经过重复节点：A -> B -> A
+  const auto lock_ids = BuildRouteLockIds({"A", "B", "A"}, true);
+
+  // 节点：A, B （A 不重复）
+  // 边：A__B, B__A （同一条边，不重复）
+  ASSERT_EQ(lock_ids.size(), 3U);
+  EXPECT_EQ(lock_ids[0], "route_node:A");
+  EXPECT_EQ(lock_ids[1], "route_node:B");
+  EXPECT_EQ(lock_ids[2], RouteLockId("A", "B"));
+}
+
 }  // namespace amr_dispatcher_core::workflow

