+  // 节点：A, B （A 不重复）
+  // 边：A__B, B__A （同一条边，不重复）
+  ASSERT_EQ(lock_ids.size(), 3U);
+  EXPECT_EQ(lock_ids[0], "route_node:A");
+  EXPECT_EQ(lock_ids[1], "route_node:B");
+  EXPECT_EQ(lock_ids[2], RouteLockId("A", "B"));
+}
