39	TrafficReservationDecision PlanTrafficBlock(
40	    const TrafficBlockRequest& request, const RouteLockMap& route_locks) {
41	  TrafficReservationDecision decision;
42	  decision.resource_id = RouteLockId(request.from_station, request.to_station);
43	  if (!request.stations_known) {
44	    decision.message = "unknown station in route block request: " + request.from_station +
45	                       " -> " + request.to_station;
46	    return decision;
47	  }
48	  if (!request.route_exists) {
49	    decision.message =
50	        "no enabled station route to block: " + request.from_station + " -> " + request.to_station;
51	    return decision;
52	  }
53	  const auto existing = route_locks.find(decision.resource_id);
54	  if (existing != route_locks.end()) {
55	    decision.message =
56	        "route resource already reserved: " + decision.resource_id + " by " + existing->second;
57	    return decision;
58	  }
59	  decision.success = true;
60	  decision.mutate_state = true;
61	  decision.owner_id = TrafficBlockOwnerId(request.reason);
62	  decision.message = "blocked route " + request.from_station + " -> " + request.to_station;
63	  return decision;
64	}
