67	    const std::string& from_station, const std::string& to_station,
68	    const RouteLockMap& route_locks) {
69	  TrafficReservationDecision decision;
70	  decision.resource_id = RouteLockId(from_station, to_station);
71	  const auto lock = route_locks.find(decision.resource_id);
72	  if (lock == route_locks.end()) {
73	    decision.message = "route resource not found: " + decision.resource_id;
74	    return decision;
75	  }
76	  decision.owner_id = lock->second;
77	  if (!IsTrafficBlockOwner(lock->second)) {
78	    decision.message = "route resource is reserved by mission: " + lock->second;
79	    return decision;
80	  }
81	  decision.success = true;
82	  decision.mutate_state = true;
83	  decision.message = "unblocked route " + from_station + " -> " + to_station;
84	  return decision;
