108	TrafficDeadlockDecision PlanTrafficDeadlockDetection(const RouteLockMap& route_locks) {
109	  TrafficDeadlockDecision decision;
110	  std::unordered_map<std::string, std::vector<std::string>> station_to_missions;
111	  std::unordered_map<std::string, std::vector<std::string>> station_to_resources;
112	  for (const auto& [resource_id, owner_id] : route_locks) {
113	    if (IsTrafficBlockOwner(owner_id)) {
114	      continue;
115	    }
116	    const auto lock = ParseRouteLock(resource_id);
117	    if (!lock.has_value()) {
118	      continue;
119	    }
120	    station_to_missions[lock->first].push_back(owner_id);
121	    station_to_missions[lock->second].push_back(owner_id);
122	    station_to_resources[lock->first].push_back(resource_id);
123	    station_to_resources[lock->second].push_back(resource_id);
124	  }
125	
126	  std::unordered_set<std::string> conflict_missions;
127	  std::unordered_set<std::string> conflict_resources;
128	  std::unordered_set<std::string> conflict_stations;
129	  for (const auto& [station_id, mission_ids] : station_to_missions) {
130	    std::unordered_set<std::string> unique_missions(mission_ids.begin(), mission_ids.end());
131	    if (unique_missions.size() < 2U) {
132	      continue;
133	    }
134	    conflict_stations.insert(station_id);
135	    std::vector<std::string> ordered_missions(unique_missions.begin(), unique_missions.end());
136	    std::sort(ordered_missions.begin(), ordered_missions.end());
137	    for (const auto& mission_id : ordered_missions) {
138	      conflict_missions.insert(mission_id);
139	    }
140	    const auto resource_it = station_to_resources.find(station_id);
141	    if (resource_it != station_to_resources.end()) {
142	      for (const auto& resource_id : resource_it->second) {
143	        conflict_resources.insert(resource_id);
144	      }
145	    }
146	    std::ostringstream desc;
147	    desc << "station " << station_id << " shared by missions ";
148	    for (std::size_t index = 0; index < ordered_missions.size(); ++index) {
149	      if (index > 0) {
150	        desc << ", ";
151	      }
152	      desc << ordered_missions[index];
153	    }
154	    decision.descriptions.push_back(desc.str());
155	  }
156	
157	  decision.deadlocked = !conflict_stations.empty();
158	  decision.mission_ids.assign(conflict_missions.begin(), conflict_missions.end());
159	  std::sort(decision.mission_ids.begin(), decision.mission_ids.end());
160	  decision.conflict_resource_ids.assign(conflict_resources.begin(), conflict_resources.end());
161	  std::sort(decision.conflict_resource_ids.begin(), decision.conflict_resource_ids.end());
162	  decision.conflict_station_ids.assign(conflict_stations.begin(), conflict_stations.end());
163	  std::sort(decision.conflict_station_ids.begin(), decision.conflict_station_ids.end());
164	  if (decision.deadlocked) {
165	    decision.message = "traffic deadlock candidates detected";
166	  }
167	  return decision;
168	}
