171	    const std::vector<std::string>& station_path, const bool include_intersection_locks) {
172	  // A10：薄封装 —— 与 dispatcher::ResourceTable::BuildLockIds 同一实现
173	  return dispatcher::ResourceTable::BuildLockIds(station_path, include_intersection_locks);
174	}
