    // action 客户端永久悬挂、handle 残留在 execute_goal_handles_（终审 F8）
    //（mission_dispatch_time_ 此刻尚未写入，无需额外遗忘）
    FinishExecuteGoal(m.id, ExecuteFinish::kAbort,
                      "unknown dropoff station: " + m.dropoff_station, 1);
